-- Voice Search — vehicles table + seed data (40 models from the prototype catalogue)
-- Run once:  mysql -u USER -p DATABASE < sql/install.sql
-- Already have a vehicles/models table? Skip CREATE, and instead add the FULLTEXT index
-- to your own table and map column names in api/search.php.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS vehicles (
  id           VARCHAR(80)  NOT NULL PRIMARY KEY,          -- slug, e.g. tata-curvv-ev
  name         VARCHAR(150) NOT NULL,
  brand        VARCHAR(80)  NOT NULL,
  type         ENUM('car','bike') NOT NULL,
  body         VARCHAR(40)  NULL,                          -- Hatchback, SUV, Scooter, Cruiser…
  fuel         VARCHAR(40)  NULL,                          -- Petrol, Diesel, CNG, Electric…
  seats        TINYINT      NULL,
  price_min    INT UNSIGNED NULL,                          -- ex-showroom, rupees
  price_max    INT UNSIGNED NULL,
  mileage      DECIMAL(6,2) NULL,                          -- kmpl, or km range for EVs
  rating       DECIMAL(2,1) NULL,
  transmission SET('manual','automatic') NULL,
  tags         TEXT NULL,                                  -- comma separated keywords
  use_cases    TEXT NULL,
  highlights   TEXT NULL,                                  -- pipe | separated, shown on cards
  features     TEXT NULL,
  url          VARCHAR(255) NULL,                          -- page URL; NULL = use url_pattern in config
  image_url    VARCHAR(255) NULL,
  status       TINYINT(1) NOT NULL DEFAULT 1,
  updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_type_price (type, price_min, price_max),
  KEY idx_brand (brand),
  FULLTEXT KEY ft_search (name, brand, body, fuel, tags, use_cases, highlights, features)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE name=VALUES(name), price_min=VALUES(price_min), price_max=VALUES(price_max);
